tools.example:
var t = app.activeDocument.activeLayer.textItem;
t.font = "Roboto-Bold";          // PostScript name, not the display name
t.size = new UnitValue(24, "pt");
// list PostScript names: for (var i=0;i<app.fonts.length;i++) $.writeln(app.fonts[i].postScriptName);

var t = app.activeDocument.activeLayer.textItem;
t.useAutoLeading = false;
t.leading = new UnitValue(30, "pt");

var c = new SolidColor();
c.rgb.hexValue = "1E88E5";
app.activeDocument.activeLayer.textItem.color = c;

var t = app.activeDocument.activeLayer.textItem;
t.kind = TextType.PARAGRAPHTEXT;
t.width = new UnitValue(400, "px"); t.height = new UnitValue(200, "px");
t.justification = Justification.LEFTJUSTIFIED;

var t = app.activeDocument.activeLayer.textItem;
t.leftIndent = new UnitValue(18, "pt");
t.firstLineIndent = new UnitValue(-18, "pt");   // hanging bullet
t.spaceAfter = new UnitValue(6, "pt");

var t = app.activeDocument.activeLayer.textItem;
t.hyphenation = true;
t.hyphenLimit = 2;
t.hyphenateCapitalWords = false;

var doc = app.activeDocument;
var lyr = doc.artLayers.add();
lyr.kind = LayerKind.TEXT;
var t = lyr.textItem;
t.kind = TextType.PARAGRAPHTEXT;
t.position = [UnitValue(50,"px"), UnitValue(50,"px")];
t.width = UnitValue(500,"px"); t.height = UnitValue(300,"px");
t.contents = "Lorem ipsum dolor sit amet, consectetur adipiscing elit.";

var t = app.activeDocument.activeLayer.textItem;
t.warpStyle = WarpStyle.ARC;
t.warpDirection = Direction.HORIZONTAL;
t.warpBend = 35;
